 Check([TFAIISHEnvironment schedule:@"backup" sessionKey:key snapshot:nil base:base error:&error],@"backup schedule");Check([Read(Join(root,@"data/a")) isEqual:@"original"],@"schedule does not mutate root");Check(![TFAIISHEnvironment schedule:@"reset" sessionKey:key snapshot:nil base:base error:&error],@"duplicate plan rejected");error=nil;
 Check([TFAIISHEnvironment applyPendingAtBase:base error:&error],@"offline backup");NSDictionary *inventory=[TFAIISHEnvironment inventoryAtBase:base];NSArray *snapshots=inventory[@"snapshots"];Check(snapshots.count==1,@"snapshot visible");NSString *identifier=snapshots[0][@"id"],*snapshot=Join(Join(Join(base,@"snapshots"),identifier),@"rootfs");struct stat a,b;stat(Join(snapshot,@"data/a").fileSystemRepresentation,&a);stat(Join(snapshot,@"data/b").fileSystemRepresentation,&b);Check(a.st_ino==b.st_ino,@"hardlinks preserved");
