 NSString *snapBase=Join(base,@"snapshots");[fm moveItemAtPath:snapBase toPath:Join(base,@"old-snapshots") error:nil];[fm createSymbolicLinkAtPath:snapBase withDestinationPath:Join(base,@"old-snapshots") error:nil];error=nil;Check(![TFAIISHEnvironment schedule:@"restore" sessionKey:key snapshot:identifier base:base error:&error],@"snapshot ancestor symlink rejected");[fm removeItemAtPath:snapBase error:nil];[fm moveItemAtPath:Join(base,@"old-snapshots") toPath:snapBase error:nil];
